--region init
function CommonActivityBossDamageBonusDialog:AddUIClick()
	SetButtonAction(self.BtnClose, Bind(self, self.OnBtnCloseHandler))
	SetButtonAction(self.Fuzzy, Bind(self, self.OnBtnCloseHandler))
	SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnOneKeyDrawHandler))
end

function CommonActivityBossDamageBonusDialog:InitData()
	local parameters = self.controller.Argument.parameters or {}
	if isNotNull(parameters.entryMgr) then
		self.entryCtrl = parameters.entryMgr
	end
	if isNull(self._damageRewardList) then
		self._damageRewardList = self.entryCtrl:GetBossHurtRewards()
	end
	
	self._historyMaxHurt = self.entryCtrl:GetBossHurt()
	self._isCanOneKeyDraw = self.entryCtrl:IsCanOneKeyDrawReward()
	self:RefreshUI()
end
--endregion init

--region handler
function CommonActivityBossDamageBonusDialog:OnBtnOneKeyDrawHandler()
	if not self._isCanOneKeyDraw then
		return
	end
	self:DrawReward(0)
end

function CommonActivityBossDamageBonusDialog:OnDrawDamageRewardHandler()
	self:InitData()
end

function CommonActivityBossDamageBonusDialog:OnBtnCloseHandler()
	UIModule.CloseDialog(self.controller)
end
--endregion handler

--region private
function CommonActivityBossDamageBonusDialog:InitItemByIndex(listView, index)
	local luaIndex = index + 1
	local cellData = self._damageRewardList[luaIndex]
	local cell = listView:NewListViewItem("Cell")
	---@type UIActivityMidFestivalBossDamageRewardCell
	local scr = CfUtils.GetLuaScr(cell, "Game.Behaviours.CommonActivityBossDamageBonusCell")
	scr:SetCallBack(function(id) self:OnDrawRewardClick(id)  end)
	local isHaveDraw = self.entryCtrl:IsHaveDrawBossHurtReward(cellData.id)
	scr:Refresh(cellData, self._historyMaxHurt, isHaveDraw)
	return cell
end

function CommonActivityBossDamageBonusDialog:OnDrawRewardClick(id)
	local idHaveDraw = self.entryCtrl:IsHaveDrawBossHurtReward(id)
	if idHaveDraw then
		GameUtils.Toast(localize("奖励已经领取"))
		return
	end
	
	self:DrawReward(id)
end

function CommonActivityBossDamageBonusDialog:DrawReward(id)
	self.entryCtrl:DrawHurtReward(id,Bind(self,self.InitData))
end

function CommonActivityBossDamageBonusDialog:RefreshUI()
	CfUtils.SetActive(self.FontStyleButton, self._isCanOneKeyDraw)
	
	if not self.DamageLoopView.IsListViewInit then
		self.DamageLoopView:InitListView(#self._damageRewardList, Bind(self, self.InitItemByIndex))
	else
		GameUtils.ReloadData(self.DamageLoopView, #self._damageRewardList)
	end
end
--endregion private

